enum device_id_t
{
  INVALID_DEVICE_ID = -1,
  JOYSTICK1_DEVICE = 1,
  AI_JOYSTICK = 9,
  KEYBOARD1_DEVICE = 10,
  MOUSE1_DEVICE = 11
};

class input_device
{
public:
  device_id_t device_id;
  virtual ~input_device();
  virtual device_id_t get_id() const;
};

template<class T>
class vector
{
public:
  typedef T* iterator;
  iterator begin();
  iterator end();
  void push_back(const T&);
};

template<class Iterator, class T>
Iterator find(Iterator first, Iterator last, const T& value)
{
  while(first != last && !(*first == value))
    ++first;
  return first;
}

typedef vector<input_device *> device_map_t;

class input_mgr
{
  char singleton_layout[8];
  void *rumble_ptr;
  device_map_t device_map;
  char control_map[12];
  int default_controller;
  unsigned int flags;
  input_device *joystick_devices[9];
  input_device *keyboard_devices[1];
  input_device *mouse_devices[1];
public:
  void insert_device(input_device * device);
};

#define IS_JOYSTICK_DEVICE(id) ((id) >= JOYSTICK1_DEVICE && (id) <= AI_JOYSTICK)
#define DEVICE_ID_TO_JOYSTICK_INDEX(id) ((id) - JOYSTICK1_DEVICE)
#define IS_KEYBOARD_DEVICE(id) ((id) >= KEYBOARD1_DEVICE && (id) <= KEYBOARD1_DEVICE)
#define DEVICE_ID_TO_KEYBOARD_INDEX(id) ((id) - KEYBOARD1_DEVICE)
#define IS_MOUSE_DEVICE(id) ((id) >= MOUSE1_DEVICE && (id) <= MOUSE1_DEVICE)
#define DEVICE_ID_TO_MOUSE_INDEX(id) ((id) - MOUSE1_DEVICE)

#define USE_STL_MAP_FOR_DEVICES 0

void input_mgr::insert_device( input_device * device )
{
#if USE_STL_MAP_FOR_DEVICES
	device_map[device->get_id()]=device;
#else
	if(find(device_map.begin(), device_map.end(), device) == device_map.end())
		device_map.push_back(device);
#endif

	if(IS_JOYSTICK_DEVICE(device->get_id()))
		joystick_devices[DEVICE_ID_TO_JOYSTICK_INDEX(device->get_id())] = device;
	else if(IS_KEYBOARD_DEVICE(device->get_id()))
		keyboard_devices[DEVICE_ID_TO_KEYBOARD_INDEX(device->get_id())] = device;
	else if(IS_MOUSE_DEVICE(device->get_id()))
		mouse_devices[DEVICE_ID_TO_MOUSE_INDEX(device->get_id())] = device;
}
